$id = 1
foreach ($book in $books) {
    $fullUrl = $baseUrl + $book.url
    $outFile = "$outDir/" + $book.filename
    Write-Host "Downloading $($book.title)..."
    try {
        Invoke-WebRequest -Uri $fullUrl -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/115.0.0.0 Safari/537.36" -OutFile $outFile -ErrorAction Stop
        Write-Host "Success: $($book.title)"
    } catch {
        Write-Host "Failed to download $($book.title): $_"
    }
}
Write-Host "Done downloading."
